+    for label in ["Strap clamp", "Built-in strap clamp", "Stud above the strap", "Clamp height", "Apply sizes"] {
+        assert_inside(&h, rect, label);
+    }
+    assert!(h.state().state.pending.is_empty(), "{:?}", h.state().state.pending);
+}

